package main

import (
    "bufio"
    "fmt"
    "io"
    "os"
    "os/exec"
    "path/filepath"
    "strings"
)

const version = "eureka 2.0.0"

func printHelp() {
    fmt.Println("Input and store your ideas without leaving the terminal")
    fmt.Println()
    fmt.Println("Usage: executable [OPTIONS]")
    fmt.Println()
    fmt.Println("Options:")
    fmt.Println("      --clear-config  Clear your stored configuration")
    fmt.Println("  -v, --view          View ideas with your $PAGER env variable. If unset use less")
    fmt.Println("  -h, --help          Print help")
    fmt.Println("  -V, --version       Print version")
}

func printFirstTime() {
    fmt.Println("############################################################")
    fmt.Println("####                  First Time Setup                  ####")
    fmt.Println("############################################################")
    fmt.Println()
    fmt.Println("This tool requires you to have a repository with a README.md")
    fmt.Println("in the root folder. The markdown file is where your ideas")
    fmt.Println("will be stored.")
    fmt.Println()
    fmt.Println("Once first time setup has completed, simply run Eureka again")
    fmt.Println("to begin writing down ideas.")
    fmt.Println()
}

func clearConfig(path string) {
    err := os.Remove(path)
    if err != nil {
        // Match message seen in original: leading space then ERROR eureka > ...
        fmt.Printf(" ERROR eureka > %s\n", err.Error())
        return
    }
    // If removed successfully print nothing
}

func viewReadme(readmePath string) {
    pager := os.Getenv("PAGER")
    if pager == "" {
        pager = "less"
    }
    // If pager contains spaces, take first token
    tokens := strings.Fields(pager)
    cmd := tokens[0]
    args := tokens[1:]
    args = append(args, readmePath)
    c := exec.Command(cmd, args...)
    c.Stdin = os.Stdin
    c.Stdout = os.Stdout
    c.Stderr = os.Stderr
    if err := c.Run(); err != nil {
        // If pager fails, fallback to catting the file
        f, ferr := os.Open(readmePath)
        if ferr != nil {
            fmt.Printf(" ERROR eureka > %s\n", ferr.Error())
            return
        }
        defer f.Close()
        io.Copy(os.Stdout, f)
    }
}

func writeConfig(path, repo string) error {
    dir := filepath.Dir(path)
    if err := os.MkdirAll(dir, 0o755); err != nil {
        return err
    }
    f, err := os.Create(path)
    if err != nil {
        return err
    }
    defer f.Close()
    _, err = f.WriteString(repo)
    return err
}

func readConfig(path string) (string, error) {
    b, err := os.ReadFile(path)
    if err != nil {
        return "", err
    }
    s := strings.TrimSpace(string(b))
    return s, nil
}

func main() {
    args := os.Args[1:]
    configPath := filepath.Join(os.Getenv("HOME"), ".config", "eureka", "config")

    if len(args) > 0 {
        switch args[0] {
        case "--help", "-h":
            printHelp()
            return
        case "-V", "--version":
            fmt.Println(version)
            return
        case "--clear-config":
            clearConfig(configPath)
            return
        case "-v", "--view":
            // try environment variable EUREKA_REPO, then config, then ./README.md
            repo := os.Getenv("EUREKA_REPO")
            if repo == "" {
                if cfg, err := readConfig(configPath); err == nil {
                    repo = cfg
                }
            }
            if repo == "" {
                // fallback to current directory
                repo = "."
            }
            readme := filepath.Join(repo, "README.md")
            if _, err := os.Stat(readme); err != nil {
                fmt.Printf(" ERROR eureka > %s\n", err.Error())
                return
            }
            viewReadme(readme)
            return
        }
    }

    // No args: first time setup if no config
    if _, err := os.Stat(configPath); err != nil {
        printFirstTime()
        // Prompt repeatedly for repo path
        reader := bufio.NewReader(os.Stdin)
        for {
            fmt.Print("Absolute path to your idea repo\n> ")
            input, err := reader.ReadString('\n')
            if err != nil {
                if err == io.EOF {
                    // If EOF, just loop to mimic original behavior of prompting again
                    continue
                }
                fmt.Printf(" ERROR eureka > %s\n", err.Error())
                return
            }
            repo := strings.TrimSpace(input)
            if repo == "" {
                continue
            }
            // Verify README.md exists in repo
            readme := filepath.Join(repo, "README.md")
            if _, err := os.Stat(readme); err != nil {
                fmt.Printf(" ERROR eureka > %s\n", err.Error())
                continue
            }
            // write config
            if err := writeConfig(configPath, repo); err != nil {
                fmt.Printf(" ERROR eureka > %s\n", err.Error())
            }
            fmt.Println("Configuration saved.")
            return
        }
    }

    // If config exists, open editor to write idea (not implemented)
    // For our reimplementation we'll just print a short note and exit
    repo, err := readConfig(configPath)
    if err != nil {
        fmt.Printf(" ERROR eureka > %s\n", err.Error())
        return
    }
    // In original, this launches editor. We'll simulate by creating a new idea entry.
    // Append a timestamped bullet to README.md
    f, err := os.OpenFile(filepath.Join(repo, "README.md"), os.O_APPEND|os.O_WRONLY, 0o644)
    if err != nil {
        fmt.Printf(" ERROR eureka > %s\n", err.Error())
        return
    }
    defer f.Close()
    _, _ = f.WriteString("- A new idea written via eureka\n")
    fmt.Println("Idea saved.")
}
EOF

